/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field SalesUnit.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(METSalesLine, CBTInvoiceNumber))]
internal class METGUPPricingAttributeMETSalesLineCBTInvoiceNumber  extends METGUPPricingAttributeMETSalesLine implements GUPIPricingAttribute
{
}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
/// <returns><c>anytype</c> object</returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).CBTInvoiceNumber;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
/// <returns>name of attribute in string</returns>
public str getName()
{
    return fieldPName(METSalesLine, CBTInvoiceNumber);
}

/// <summary>
/// Get attribte data type
/// </summary>
/// <returns><c>AttributeDataType</c> object</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Text;
}

/// <summary>
/// return sales unit field.
/// </summary>
/// <returns><c>FieldId</c> value</returns>
public FieldId getField()
{
    return fieldNum(METSalesLine, CBTInvoiceNumber);
}

/// <summary>
/// Gets the path of the attribute tables
/// </summary>
/// <returns>'PATH_NOT_EXIST'</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7',
        tableStr(SalesLine),
        tableStr(METSalesLine),
        fieldStr(SalesLine, RecId),
        fieldStr(METSalesLine, SalesLine),
        tableStr(METSalesLine),
        fieldStr(METSalesLine, CBTInvoiceNumber),
        this.getAttributeFieldIdentifier());
}
